process.env.VERCEL='1';process.env.DATABASE_URL=pg.connectionUrl;
const proxy=new Proxy(pg.db,{get:(t,k)=>k==='end'?async()=>{}:Reflect.get(t,k)});
const db=loadDeep('lib/db.ts',{'postgres':()=>proxy});
const guard=pg.load('lib/orderDelivery.ts');
const req=(method,body)=>new Request('http://local/api/orders/expedition',{method,body:JSON.stringify({orderId:id,...body})});
try{
 await pg.migrate();
 await pg.db`ALTER TABLE orders ADD COLUMN poster_confirmation_email text, ADD COLUMN poster_confirmation_token text, ADD COLUMN poster_confirmation_sent_at timestamptz, ADD COLUMN poster_confirmation_responded_at timestamptz, ADD COLUMN poster_confirmation_message_id text, ADD COLUMN last_outbound_message_id text`;
 const reset=async(opts={printKey:'digital'})=>{await pg.db`DELETE FROM order_delivery_effects`;await pg.db`DELETE FROM orders`;await pg.db`INSERT INTO orders(id,status,paid_at,customer_email,customer_name,langue,detected_country,options,final_image_url) VALUES(${id},'in_progress',now(),'new@example.invalid','Buyer','en','FR',${pg.db.json(opts)},'https://synthetic.invalid/final/A.png')`;};
 await reset({printKey:'canvas'});
 await pg.db`UPDATE orders SET poster_confirmation_status='confirmed',poster_confirmation_image_url=final_image_url,poster_confirmation_email='old@example.invalid',poster_confirmation_token='old-invitation' WHERE id=${id}`;
 let sent=[];
 const helper=loadDeep('lib/emailImageFinale.ts',{
 '@/lib/db':db,'@/lib/orderDelivery':guard,
 '@/lib/finalImage':{validateFinalImageUrl:()=>{},downloadFinalImage:async()=>({bytes:Buffer.from('A')}),FinalImageError:class extends Error{constructor(m,s){super(m);this.status=s;}}},
 '@/lib/emailToken':{orderTrackingToken:()=> 'synthetic'},'@/lib/analyticsServeur':{mesureServeur:async()=>{}},'@/lib/parrainage':{infosParrainage:async()=>null},'@/lib/envoiEmail':{envoyerEmail:async p=>{sent.push(p.to);return {data:{id:'captured-approval'}};}}});
 const lookup=await db.getOrderByConfirmationToken('old-invitation');
 const result=await helper.envoyerImageFinale(await db.getOrderById(id));
 out.approval_email_mismatch={accepted:true,result,sent,canonicalInvitationLookup:lookup,order:(await pg.db`SELECT customer_email,poster_confirmation_email,poster_confirmation_status,final_image_sent_at FROM orders WHERE id=${id}`)[0]};
 assert.equal(lookup,null);assert.equal(sent.length,1);
 await reset({printKey:'digital',carteVoeux:true});
 const a=await db.getOrderById(id);
 await guard.executeDelivery(a,'final_image',guard.deliveryContentHash(Buffer.from('A')),a.customer_email,async ctx=>ctx.send(async()=>({data:{id:'portrait-A-delivered'}})));
 const marker=(await db.getOrderById(id)).final_image_sent_at;
 await db.updateOrderFinalImage(id,'https://synthetic.invalid/final/B.png');
 let extrasSends=0,uploads=0;const downloaded=[];
 const extra=load('app/api/orders/extras/route.ts',{
 '@/lib/db':db,'@/lib/orderDelivery':guard,'@/lib/adminAuth':{refuserSiPasAdmin:async()=>null},
 '@/lib/finalImage':{downloadFinalImage:async url=>{downloaded.push(url);return {bytes:Buffer.from('B')};},FinalImageError:class extends Error{}},
 '@/lib/extras/carteVoeux':{genererCarteVoeux:async()=>Buffer.from('synthetic-pdf-B')},'@/lib/extras/calendrier':{genererCalendrier:async()=>Buffer.from('unused')},
 '@vercel/blob':{put:async()=>{uploads++;return {url:'https://synthetic.invalid/B.pdf'};}},'@/lib/envoiEmail':{envoyerEmail:async()=>{extrasSends++;return {data:{id:'extras-B'}};}}});
 const response=await extra.POST(req('POST',{}));
 out.extras_undelivered_retouch={status:response.status,body:await response.json(),sends:extrasSends,uploads,downloaded,oldDeliveryMarkerPreserved:new Date((await db.getOrderById(id)).final_image_sent_at).getTime()===new Date(marker).getTime(),effects:await pg.db`SELECT kind,status,email_id FROM order_delivery_effects ORDER BY kind`};
 assert.equal(response.status,200);assert.equal(extrasSends,1);
 const shipping=pg.load('lib/orderDeliveryShipping.ts');
 for(const method of ['PATCH','POST']){
 await reset({printKey:'canvas'});await pg.db`UPDATE orders SET customer_email='old@example.invalid' WHERE id=${id}`;
 let mails=[];let mutated=false;
 const route=load('app/api/orders/expedition/route.ts',{'@/lib/adminAuth':{refuserSiPasAdmin:async()=>null},'@/lib/orderDeliveryShipping':shipping,
 '@/lib/db':{...db,getOrderById:async orderId=>{const stale=await db.getOrderById(orderId);if(!mutated){mutated=true;await pg.db`UPDATE orders SET customer_email='new@example.invalid',final_image_url='https://synthetic.invalid/final/B.png',options='{"printKey":"framed"}' WHERE id=${id}`;}return stale;}},
 '@/lib/envoiEmail':{envoyerEmail:async p=>{mails.push({to:p.to});return {data:{id:'shipping-captured'}};}}});
 const r=await route[method](req(method,{fournisseurRef:'REF',suiviUrl:'https://tracking.invalid/parcel-A',transporteur:'DHL'}));
 out['shipping_stale_'+method]={status:r.status,body:await r.json(),mails,order:(await pg.db`SELECT customer_email,final_image_url,options,cout,cout_note,expedie_le,expedition_email_envoye_le FROM orders WHERE id=${id}`)[0]};
 assert.equal(r.status,200);assert.equal(mails.length,method==='POST'?1:0);
 }
 await reset({printKey:'canvas'});
 let attempted=0;
 const refusal=load('app/api/orders/expedition/route.ts',{'@/lib/adminAuth':{refuserSiPasAdmin:async()=>null},'@/lib/orderDeliveryShipping':shipping,'@/lib/db':db,'@/lib/envoiEmail':{envoyerEmail:async()=>{attempted++;return {data:null,error:{message:'synthetic provider refusal'}};}}});
 const r=await refusal.POST(req('POST',{suiviUrl:'https://tracking.invalid/rejected'}));out.shipping_provider_refusal={status:r.status,body:await r.json(),attempted,order:(await pg.db`SELECT expedie_le,expedition_email_envoye_le FROM orders WHERE id=${id}`)[0]};assert.equal(r.status,200);
 console.log(JSON.stringify(out,null,2));
}finally{await pg.close();}
